import { readAccountLoan, previewAccountLoan, borrowAgainstAccount, repayAccountLoan, withdrawAccountAfkingCredit } from '../app/account-loans.js';
import { get, subscribe, deriveCanSign } from '../app/store.js';
import { ETH_DIVISOR } from '../app/chain-config.js';
import { displayEthCompact } from '../app/scaling.js';
import { compactUiError } from '../app/ui-error.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';

// Mirrors the game's LOAN_MIN_PRINCIPAL (testnet-scaled like every ETH constant) and repay() terms.
const MIN_PRINCIPAL = 50_000_000_000_000_000n / ETH_DIVISOR;
const STEPS = 1000n;
const QUOTE_DELAY_MS = 200;

export function minRepayment(principal, start, due) {
  const term = BigInt(due - start);
  return principal * (10_000n + 500n + (term > 1n ? term - 1n : 0n) * 100n) / 10_000n;
}

/** The most `principal` can cost to repay: the last repayable level of a loan taken at `start`. */
export function maxRepayment(principal, start, due) {
  const term = BigInt(due - start);
  const used = term > 1n ? term - 1n : 1n;
  return principal * (10_000n + used * 500n + (term - used) * 100n) / 10_000n;
}

export function closeAccountLoan() { closePanelPopup('liquidation', { restoreFocus: false }); }

export function openAccountLoan({ player, trigger, onSold, onClose } = {}) {
  closeAccountLoan();
  const panel = document.createElement('section');
  panel.className = 'panel-popup liquidation-popup pawn-popup';
  panel.id = 'panel-liquidation'; panel.dataset.panelPopup = 'liquidation'; panel.hidden = true;
  panel.setAttribute('role', 'dialog'); panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'account-loan-title');
  panel.innerHTML = `<div class="panel-popup__window">
    <header class="panel-popup__header"><h2 id="account-loan-title">LOANS</h2>
      <button type="button" class="panel-popup__close" data-panel-close aria-label="Close loans">×</button></header>
    <div class="panel-popup__body">
      <div class="pawn-offer" data-loan="offer" hidden>
        <label class="pawn-slider"><span>REPAY BY <b>LEVEL <output data-loan="due-value">—</output></b></span>
          <input data-loan="due" type="range" step="1" aria-label="Repay by level"></label>
        <div class="pawn-figure"><span>MAX LOAN</span><strong data-loan="max">—</strong></div>
        <label class="pawn-slider"><span>BORROW <b><output data-loan="amount-value">—</output></b></span>
          <input data-loan="amount" type="range" min="0" max="${STEPS}" step="1" value="${STEPS}" aria-label="Loan amount"></label>
        <dl class="pawn-terms pawn-terms--quote"><div><dt>YOU GET</dt><dd data-loan="get">—</dd></div>
          <div><dt>REPAY MIN</dt><dd data-loan="owe-min">—</dd></div>
          <div><dt>REPAY MAX</dt><dd data-loan="owe">—</dd></div></dl>
      </div>
      <div class="pawn-offer" data-loan="open" hidden>
        <div class="pawn-figure"><span>REPAY NOW</span><strong data-loan="owed">—</strong></div>
        <dl class="pawn-terms"><div><dt>BORROWED</dt><dd data-loan="principal">—</dd></div>
          <div><dt>DUE BY</dt><dd data-loan="due-by">—</dd></div></dl>
      </div>
      <div data-loan="credit" hidden><p>AFKing balance: <strong data-loan="balance">—</strong></p></div>
      <p class="pawn-warning">Fail to repay and your entire account is seized.</p>
      <p class="pawn-status" data-loan="status" role="status" aria-live="polite"></p>
      <div class="liquidation-actions"><button type="button" data-loan="borrow" disabled hidden>BORROW</button>
        <button type="button" data-loan="repay" disabled hidden>REPAY</button>
        <button type="button" data-loan="withdraw" disabled hidden>WITHDRAW</button></div>
    </div></div>`;
  document.body.appendChild(panel);
  const node = key => panel.querySelector(`[data-loan="${key}"]`);
  const eth = value => `${displayEthCompact(value, 4)} ETH`;
  let account, quote, busy = false, closed = false, sequence = 0, timer = null, duePicked = false;
  const cleanups = [];
  const owns = () => deriveCanSign() && get('ui.mode') === 'self'
    && String(get('connected.address')).toLowerCase() === String(player).toLowerCase()
    && account?.payee === String(player).toLowerCase();
  const status = text => { node('status').textContent = text; };
  function sync() {
    node('borrow').disabled = busy || !owns() || !quote?.eligible;
    node('repay').disabled = busy || !owns() || !(account?.owed > 0n);
    node('withdraw').disabled = busy || !owns() || !(account?.afkingCredit > 0n);
    node('due').disabled = busy; node('amount').disabled = busy;
  }
  // The amount slider is a share of whatever the chosen term allows, so moving the
  // repayment level keeps the borrower's relative choice.
  function chosenAmount(max) {
    const share = max * BigInt(node('amount').value) / STEPS;
    return share < MIN_PRINCIPAL ? MIN_PRINCIPAL : share;
  }
  function renderQuote() {
    node('due-value').textContent = node('due').value;
    if (!quote) { node('get').textContent = '…'; node('owe-min').textContent = '…'; node('owe').textContent = '…'; return; }
    const available = quote.maxPrincipal >= MIN_PRINCIPAL;
    node('max').textContent = eth(quote.maxPrincipal);
    node('amount-value').textContent = available ? eth(quote.principal) : '—';
    node('get').textContent = available ? eth(quote.afkingCredit) : '—';
    node('owe-min').textContent = available ? eth(minRepayment(quote.principal, account.level, quote.dueLevel)) : '—';
    node('owe').textContent = available ? eth(maxRepayment(quote.principal, account.level, quote.dueLevel)) : '—';
    status(!available ? 'Nothing available to borrow.'
      : quote.eligible ? '' : quote.lenderId ? 'No loan is available right now.' : 'Not enough cash to lend this much right now.');
  }
  async function refreshQuote() {
    const seq = ++sequence;
    try {
      const dueLevel = node('due').value;
      let next = await previewAccountLoan({ player, accountId: account.accountId, dueLevel });
      if (closed || seq !== sequence) return;
      const amount = chosenAmount(next.maxPrincipal);
      if (next.maxPrincipal >= MIN_PRINCIPAL && amount < next.maxPrincipal) {
        next = await previewAccountLoan({ player, accountId: account.accountId, dueLevel, amount });
        if (closed || seq !== sequence) return;
      }
      quote = next; renderQuote();
      if (!owns()) status('Connect the account owner wallet to borrow.');
    } catch (error) { if (!closed && seq === sequence) status(compactUiError(error, 'Could not load the loan offer.')); }
    finally { if (!closed && seq === sequence) sync(); }
  }
  function scheduleQuote() {
    quote = null; renderQuote(); node('borrow').disabled = true;
    clearTimeout(timer); timer = setTimeout(() => { timer = null; void refreshQuote(); }, QUOTE_DELAY_MS);
  }
  async function load() {
    const seq = ++sequence; busy = true; quote = null;
    status('Loading…'); sync();
    try {
      const next = await readAccountLoan({ player });
      if (closed || seq !== sequence) return;
      account = next;
      if (!account.accountId) throw new Error('This wallet has no game account.');
      node('balance').textContent = eth(account.afkingCredit);
      node('credit').hidden = !(account.afkingCredit > 0n);
      node('withdraw').hidden = !(account.afkingCredit > 0n);
      const open = account.principal > 0n;
      node('offer').hidden = open; node('borrow').hidden = open;
      node('open').hidden = !open; node('repay').hidden = !open;
      if (open) {
        node('owed').textContent = account.owed > 0n ? eth(account.owed) : '—';
        node('principal').textContent = eth(account.principal);
        node('due-by').textContent = `LEVEL ${account.dueLevel}`;
        status(account.owed > 0n ? (owns() ? '' : 'Connect the account owner wallet to repay.')
          : 'The due level has arrived; repayment is no longer available.');
        return;
      }
      const due = node('due');
      const min = account.level + 1, max = Math.max(min, account.maxDueLevel);
      due.min = String(min); due.max = String(max);
      // An untouched range input reads as its midpoint, so only a moved slider survives a reload.
      due.value = String(Math.min(max, Math.max(min, duePicked ? Number(due.value) : account.level + 5)));
      busy = false; status('');
      await refreshQuote();
    } catch (error) { if (!closed && seq === sequence) status(compactUiError(error, 'Could not load the loan offer.')); }
    finally { if (!closed && seq === sequence) { busy = false; sync(); } }
  }
  async function act(kind) {
    if (busy || node(kind).disabled) return;
    busy = true; sequence++; clearTimeout(timer); status('Confirm the transaction in your wallet…'); sync();
    try {
      const result = kind === 'borrow'
        ? await borrowAgainstAccount({ player, accountId: account.accountId, dueLevel: quote.dueLevel, amount: quote.principal, minAfkingCredit: quote.afkingCredit })
        : kind === 'withdraw'
          ? await withdrawAccountAfkingCredit({ player, accountId: account.accountId, amount: account.afkingCredit })
          : await repayAccountLoan({ player, accountId: account.accountId, maxOwed: account.owed });
      try { await onSold?.(result); } catch { /* regular polling retries the view refresh */ }
      if (!closed) { busy = false; await load();
        if (kind === 'borrow') status('Loan confirmed.');
      }
    } catch (error) {
      if (!closed) { quote = null; status(compactUiError(error, 'Transaction did not complete. Try again.')); }
    } finally { busy = false; if (!closed) sync(); }
  }
  node('due').addEventListener('input', () => { duePicked = true; scheduleQuote(); });
  node('amount').addEventListener('input', () => {
    // Show the slider position at once; the exact credit follows the debounced quote.
    if (quote) node('amount-value').textContent = eth(chosenAmount(quote.maxPrincipal));
    scheduleQuote();
  });
  node('borrow').addEventListener('click', () => { void act('borrow'); });
  node('withdraw').addEventListener('click', () => { void act('withdraw'); });
  node('repay').addEventListener('click', () => { void act('repay'); });
  panel.addEventListener('app:panel-close', () => {
    if (closed) return; closed = true; sequence++; clearTimeout(timer); cleanups.forEach(fn => fn()); panel.remove(); onClose?.();
  });
  for (const path of ['connected.address', 'viewing.address', 'ui.mode']) cleanups.push(subscribe(path, () => closePanelPopup('liquidation', { restoreFocus: false })));
  cleanups.push(subscribe('ui.chainOk', sync));
  openPanelPopup('liquidation', trigger, panel); void load();
}
